public static class PhoneLetters {
    // The letters printed on each key. 0 and 1 have none.
    private static readonly string[] Keys = { "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz" };

    public static IList<string> Combinations(string digits) {
        var result = new List<string>();
        if (string.IsNullOrEmpty(digits)) return result;              // nothing typed: no combinations
        foreach (char d in digits)
            if (d < '2' || d > '9') throw new ArgumentException("only the digits 2-9 have letters: " + d);
        var current = new char[digits.Length];                       // the letter chosen for each position
        Build(digits, 0, current, result);
        return result;
    }

    // Choose a letter for position i, then fill the rest. The recursion is only as deep as the number of digits.
    private static void Build(string digits, int i, char[] current, List<string> result) {
        if (i == digits.Length) { result.Add(new string(current)); return; }
        foreach (char letter in Keys[digits[i] - '0']) {
            current[i] = letter;
            Build(digits, i + 1, current, result);
        }
    }
}
